"""Billing for readings. Rate lookups are billed, so the charge is remembered."""
import rates


class ReadingBill:
    def __init__(self):
        self._readings = []
        self._charge = None

    def add(self, reading):
        """Add one reading to the bill."""
        self._readings.append(reading)

    def charge(self):
        """Return the total charge: level times the rate for each reading's sensor.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.level * rates.rate_for(x.sensor) for x in self._readings)
        return self._charge

